local HorseBreeder = {}
local PRODUCTS = {
    pack_horse = { name = "Tovorni konj", horseCost = 1, fodderCost = 2, waterCost = 1, time = 5, cost = 50, yield = 40, happiness = 1, description = "Tovorni konj za prevoz." },
    riding_horse = { name = "Jahači konj", horseCost = 1, fodderCost = 2, waterCost = 1, time = 6, cost = 80, yield = 55, prestige = 2, description = "Jahači konj za viteze." },
    war_horse = { name = "Bojni konj", horseCost = 1, fodderCost = 3, waterCost = 1, time = 8, cost = 180, yield = 70, prestige = 5, happiness = 1, description = "Bojni konj za konjenico." },
    silver_maned_horse = { name = "Srebrnogrivi konj", horseCost = 1, silverCost = 1, fodderCost = 2, waterCost = 1, time = 11, cost = 420, yield = 85, prestige = 11, happiness = 2, description = "Srebrnogrivi konj za plemiče." },
    silver_bell_destrier = { name = "Srebrno zvončni destrier", horseCost = 2, silverCost = 1, fodderCost = 3, waterCost = 1, time = 14, cost = 900, yield = 92, prestige = 20, happiness = 4, description = "Destrier s srebrnim zvonom za visoke plemiče." },
    royal_grand_steed = { name = "Kraljevski veliki bojni konj", horseCost = 3, goldCost = 1, silverCost = 1, jewelCost = 1, fodderCost = 4, waterCost = 2, time = 20, cost = 2500, yield = 100, prestige = 55, happiness = 12, description = "Veliki kraljevski bojni konj z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Konjerejska postaja", cost = { gold = 300, wood = 140, stone = 200 }, upkeep = 7, qualityBonus = 5 },
    stud_farm = { name = "Žrebec farma", cost = { gold = 1100, wood = 280, stone = 400, fodder = 10 }, upkeep = 28, qualityBonus = 18 },
    training_arena = { name = "Dresurna arena", cost = { gold = 2600, wood = 400, stone = 700, silver = 40, iron = 10 }, upkeep = 65, qualityBonus = 30 },
    royal_stud_atelier = { name = "Kraljevski atelje konjereje", cost = { gold = 10000, wood = 700, stone = 1000, gold = 80, jewel = 25 }, upkeep = 200, qualityBonus = 55, prestigeBonus = 45 },
}
HorseBreeder.horseStock = 18; HorseBreeder.fodderStock = 24; HorseBreeder.waterStock = 18; HorseBreeder.silverStock = 8; HorseBreeder.goldStock = 6; HorseBreeder.jewelStock = 6
HorseBreeder.productStock = {}; HorseBreeder.buildings = {}; HorseBreeder.maker = nil; HorseBreeder.activeMaking = {}; HorseBreeder.totalProducts = 0; HorseBreeder.dayTimer = 0
function HorseBreeder.init() HorseBreeder.horseStock=18; HorseBreeder.fodderStock=24; HorseBreeder.waterStock=18; HorseBreeder.silverStock=8; HorseBreeder.goldStock=6; HorseBreeder.jewelStock=6; HorseBreeder.productStock={}; HorseBreeder.buildings={}; HorseBreeder.maker=nil; HorseBreeder.activeMaking={}; HorseBreeder.totalProducts=0; HorseBreeder.dayTimer=0; print("[HorseBreeder] Royal Horse Breeder System initialized (6 products, 4 buildings)") end
function HorseBreeder.hireMaker(n,s) s=s or math.random(50,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HorseBreeder.maker={name=n or ("Konjerejec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Konjerejec najet: %s (spretnost: %d)",HorseBreeder.maker.name,s),"success") end; return true end
function HorseBreeder.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HorseBreeder.build(id) local ok,e=HorseBreeder.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HorseBreeder.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HorseBreeder.getQualityBonus() local b=0; for _,bd in ipairs(HorseBreeder.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HorseBreeder.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.horseCost and HorseBreeder.horseStock<(d.horseCost or 0) then return false,"Premalo konj" end; if d.fodderCost and HorseBreeder.fodderStock<(d.fodderCost or 0) then return false,"Premalo krme" end; if d.waterCost and HorseBreeder.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.silverCost and HorseBreeder.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HorseBreeder.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HorseBreeder.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #HorseBreeder.buildings==0 then return false,"Potrebna delavnica" end; if not HorseBreeder.maker then return false,"Potreben konjerejec" end; return true end
function HorseBreeder.make(pt,qty) qty=qty or 1; local ok,e=HorseBreeder.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.horseCost then HorseBreeder.horseStock=HorseBreeder.horseStock-d.horseCost*qty end; if d.fodderCost then HorseBreeder.fodderStock=HorseBreeder.fodderStock-d.fodderCost*qty end; if d.waterCost then HorseBreeder.waterStock=HorseBreeder.waterStock-d.waterCost*qty end; if d.silverCost then HorseBreeder.silverStock=HorseBreeder.silverStock-d.silverCost*qty end; if d.goldCost then HorseBreeder.goldStock=HorseBreeder.goldStock-d.goldCost*qty end; if d.jewelCost then HorseBreeder.jewelStock=HorseBreeder.jewelStock-d.jewelCost*qty end; local t=d.time; if HorseBreeder.maker then t=math.max(1,t-math.floor(HorseBreeder.maker.skill/12)) end; table.insert(HorseBreeder.activeMaking,{id="horse_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,yield=d.yield or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HorseBreeder.completeMaking(m) local q=1.0+(HorseBreeder.getQualityBonus()/100); if HorseBreeder.maker then q=q+(HorseBreeder.maker.skill/150) end; q=math.min(2.5,q); HorseBreeder.productStock[m.productType]=(HorseBreeder.productStock[m.productType] or 0)+m.quantity; HorseBreeder.totalProducts=HorseBreeder.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HorseBreeder.maker then HorseBreeder.maker.itemsMade=HorseBreeder.maker.itemsMade+m.quantity; if math.random()<0.25 then HorseBreeder.maker.skill=math.min(100,HorseBreeder.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Konj vzrejen: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"horse.completed",{productName=m.productName,yield=m.yield,prestige=m.prestige,happiness=m.happiness}) end end
function HorseBreeder.update(dt) if not _G.state then return end; HorseBreeder.dayTimer=HorseBreeder.dayTimer+dt; if HorseBreeder.dayTimer>=30 then HorseBreeder.dayTimer=0; for i=#HorseBreeder.activeMaking,1,-1 do local m=HorseBreeder.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HorseBreeder.completeMaking(m); table.remove(HorseBreeder.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HorseBreeder.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HorseBreeder.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HorseBreeder.getStats() return {horseStock=HorseBreeder.horseStock,fodderStock=HorseBreeder.fodderStock,waterStock=HorseBreeder.waterStock,silverStock=HorseBreeder.silverStock,goldStock=HorseBreeder.goldStock,jewelStock=HorseBreeder.jewelStock,productStock=HorseBreeder.productStock,numBuildings=#HorseBreeder.buildings,hasMaker=HorseBreeder.maker~=nil,makerName=HorseBreeder.maker and HorseBreeder.maker.name or "—",makerSkill=HorseBreeder.maker and HorseBreeder.maker.skill or 0,activeMaking=#HorseBreeder.activeMaking,totalProducts=HorseBreeder.totalProducts} end
return HorseBreeder
